const cfg = $item(0).$node['Config'].json || {};
+const rows = $items('Fetch Legacy Release Candidates').map((i) => i.json || {});
+
+const locationId = String(cfg.locationId || '').trim();
+const apiBaseUrl = String(cfg.ghlApiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
+const apiKey = String(cfg.ghlApiKey || '').trim();
+const backfillTag = String(cfg.backfillTag || 'Seq Emerald - Intro Backfill Pending').trim();
+const alreadySentTag = String(cfg.alreadySentTag || 'Seq Emerald - Intro Sent').trim().toLowerCase();
+const dryRun = !!cfg.defaultDryRun;
+
+if (!locationId) throw new Error('Missing Config.locationId');
+if (!dryRun && !apiKey) throw new Error('Missing Config.ghlApiKey for live mode');
+
+function clean(v) { return String(v ?? '').trim(); }
+
+async function doHttpRequest(options) {
+  if (typeof $httpRequest === 'function') return await $httpRequest(options);
+  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
+  throw new Error('HTTP helper not available');
+}
+
+const headers = {
+  Authorization: `Bearer ${apiKey}`,
+  Version: '2021-07-28',
+  'Content-Type': 'application/json',
+  Accept: 'application/json',
+};
+
+async function apiRequest({ method, path, body }) {
+  const options = { method, url: `${apiBaseUrl}${path}`, headers, json: true };
+  if (body !== undefined) options.body = body;
+  try {
+    const data = await doHttpRequest.call(this, options);
+    return { ok: true, data };
+  } catch (err) {
+    return {
+      ok: false,
+      status: err?.statusCode || err?.httpCode || 500,
+      data: err?.response?.body || err?.message || err,
+    };
+  }
+}
+
+async function resolveContactId(candidate) {
+  const fromId = clean(candidate.ghl_contact_id);
+  if (fromId) return { ok: true, contactId: fromId, resolvedVia: 'release_log_id' };
+
+  const email = clean(candidate.contact_email).toLowerCase();
+  if (!email) return { ok: false, reason: 'missing_id_and_email' };
+
+  const dup = await apiRequest.call(this, {
+    method: 'GET',
+    path: `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&email=${encodeURIComponent(email)}`,
+  });
+  if (!dup.ok) return { ok: false, reason: 'duplicate_lookup_failed', details: dup.data };
+
+  const id = clean(dup.data?.contact?.id || dup.data?.id || dup.data?.contactId || '');
+  if (!id) return { ok: false, reason: 'email_lookup_no_match' };
+  return { ok: true, contactId: id, resolvedVia: 'email_duplicate_lookup' };
+}
+
+const dedupe = new Map();
+for (const row of rows) {
+  const key = clean(row.ghl_contact_id) || clean(row.contact_email).toLowerCase();
+  if (!key) continue;
+  if (!dedupe.has(key)) dedupe.set(key, row);
+}
+const candidates = Array.from(dedupe.values());
+
+const results = [];
+for (const c of candidates) {
+  const resolved = dryRun
+    ? { ok: true, contactId: clean(c.ghl_contact_id) || null, resolvedVia: clean(c.ghl_contact_id) ? 'release_log_id' : 'dryrun_email_only' }
+    : await resolveContactId.call(this, c);
+
+  if (!resolved.ok || !resolved.contactId) {
+    results.push({ status: 'skipped_unresolved', reason: resolved.reason || 'unresolved', contact_email: c.contact_email || null, details: resolved.details || null });
+    continue;
+  }
+
+  if (dryRun) {
+    results.push({ status: 'planned', contactId: resolved.contactId, contact_email: c.contact_email || null, first_release_ts: c.first_release_ts || null, resolvedVia: resolved.resolvedVia });
+    continue;
+  }
+
+  const contactRes = await apiRequest.call(this, { method: 'GET', path: `/contacts/${encodeURIComponent(resolved.contactId)}` });
+  if (!contactRes.ok) {
+    results.push({ status: 'error_contact_read', contactId: resolved.contactId, details: contactRes.data });
+    continue;
+  }
+
+  const tagList = Array.isArray(contactRes.data?.contact?.tags)
+    ? contactRes.data.contact.tags
+    : Array.isArray(contactRes.data?.tags)
+      ? contactRes.data.tags
+      : [];
+  const tagSet = new Set(tagList.map((t) => clean(t).toLowerCase()).filter(Boolean));
+
+  if (tagSet.has(alreadySentTag)) {
+    results.push({ status: 'skipped_already_intro_sent', contactId: resolved.contactId });
+    continue;
+  }
+
+  if (tagSet.has(clean(backfillTag).toLowerCase())) {
+    results.push({ status: 'already_backfill_tagged', contactId: resolved.contactId });
+    continue;
+  }
+
+  const tagRes = await apiRequest.call(this, {
+    method: 'POST',
+    path: `/contacts/${encodeURIComponent(resolved.contactId)}/tags`,
+    body: { tags: [backfillTag] },
+  });
+  if (!tagRes.ok) {
+    results.push({ status: 'error_tag_add', contactId: resolved.contactId, details: tagRes.data });
+    continue;
+  }
+
+  results.push({ status: 'tagged', contactId: resolved.contactId, contact_email: c.contact_email || null });
+}
+
+const summary = {
+  ok: true,
+  dryRun,
+  cutoff: cfg.legacyCutoffTs,
+  rowsFromQuery: rows.length,
+  uniqueCandidates: candidates.length,
+  planned: results.filter((r) => r.status === 'planned').length,
+  tagged: results.filter((r) => r.status === 'tagged').length,
+  skippedUnresolved: results.filter((r) => r.status === 'skipped_unresolved').length,
+  skippedAlreadySent: results.filter((r) => r.status === 'skipped_already_intro_sent').length,
+  alreadyBackfillTagged: results.filter((r) => r.status === 'already_backfill_tagged').length,
+  errors: results.filter((r) => String(r.status || '').startsWith('error_')).length,
+};
+
+return [{ json: { summary, sample: results.slice(0, 250) } }];
